function parseStatus(raw) {
 const v={}, rows={};
 raw=String(raw||'').replace(/\\r\\n|\\n/g,'\n').replace(/<br\s*\/?\s*>/gi,'\n');
 const names='状态|好感|爱意|碎碎念|待办|关于你|许愿盒|便利贴|纪念日|恋爱笔记|炒菜笔记|偏好|蝴蝶|画本|日记|附件|随笔|欲念';
