 const parts=(prefix,s,max,lines=false)=>{let a=(s||'').split(lines?/\r?\n/:/\r?\n\s*\r?\n/);if(a.length>max)a=[...a.slice(0,max-1),a.slice(max-1).join('\n')];a.forEach((x,i)=>v[prefix+(i+1)]=x.trim());if(!a[0])v[prefix+'1']='无';};
 set(['clothes','mood','action','impression'],fields('状态').map(x=>val(x)));
 for(const [n,k] of [['好感','favor'],['爱意','love']]) {let a=fields(n);set([k,k+'_delta',k+'_reason'],[val(a[0],'-'),val(a[1],'-'),val(a[2],'-')]);if(Number.isFinite(number(a[0])))v[k]=String(number(a[0]));if(empty(a[1])||number(a[1])===0){v[k+'_delta']='';v[k+'_reason']='';}v[k+'_pink']=number(a[0])>=60?v[k]:'';v[k+'_infinite']=a[0]==='∞'?'∞':'';}
 set(['thought1','thought2','thought3'],fields('碎碎念').map(x=>val(x)));
 list('待办').slice(0,5).forEach((x,i)=>{let m=x.match(/^([□✓✔☑☐✅√])\s*(.*)$/);v['todo'+(i+1)+'_done']=m&&/[✓✔☑✅√]/.test(m[1])?'✓':'□';v['todo'+(i+1)+'_text']=m?m[2]:x;});
 for(const [n,k] of [['关于你','about'],['偏好','pref']])list(n).slice(0,5).forEach((x,i)=>{let m=x.match(/^([^：:]+)[：:]([\s\S]*)$/);v[k+(i+1)+'_label']=m?m[1]:'';v[k+(i+1)+'_text']=m?m[2]:x;});
 for(const [n,k] of [['许愿盒','wish'],['便利贴','note'],['附件','attachment']])list(n).slice(0,5).forEach((x,i)=>v[k+(i+1)]=x);
