 const context=()=>{try{return host.SillyTavern?.getContext?.()||{};}catch{return {};}};
 const on=(target,name,fn)=>{target.addEventListener(name,fn);off.push(()=>target.removeEventListener(name,fn));};
 const hidden=()=>doc.hidden||local.document.hidden;
