  else if(c.chat?.length){const m=c.chat[0];first={message:m.mes,swipe_id:m.swipe_id};}
  const identity=String(c.getCurrentChatId?.()??c.chatId??'')+'|'+String(c.characterId??'');
  if(!first)return {id:identity,missing:!!get||Array.isArray(c.chat),text:null};
  const text=first.message??first.swipes?.[first.swipe_id||0]??'';
  return {id:JSON.stringify([identity,first.swipe_id??0,text]),missing:false,text};
 }
 function matches(s){if(s.text===null)return !s.missing;if(options.home)return /^\s*(?:开场白|<xjw_home\s*\/>)\s*$/.test(s.text);
  const m=s.text.match(/<mp3_player>\s*\[Track\|[^\]]*\]\s*\[Media\|[^|]*\|([^\]]*)\]\s*<\/mp3_player>/s);return !!m&&m[1].trim()===options.key.trim();}
 function paint(){options.paint?.();}
 function pause(manual=true){wanted=false;blocked=false;version++;audio.pause();if(manual&&baseline)shared.paused.add(baseline.id);paint();}
 function stop(){if(dead)return;dead=true;pause(false);clearInterval(timer);off.splice(0).forEach(f=>{try{f();}catch{}});audio.removeAttribute('src');audio.load();if(shared.active===controller)shared.active=null;}
 async function check(){if(dead)return false;if(!attached()){stop();return false;}if(hidden()){pause();return false;}const s=await snapshot();if(dead)return false;if(!baseline||s.missing||s.id!==baseline.id||!matches(s)){stop();return false;}return true;}
 async function play(){const token=++version;if(dead||hidden()||!wanted)return;try{if(!await check()||token!==version||!wanted)return;
  if(shared.active!==controller){shared.active?.stop();shared.active=controller;}
  await audio.play();if(dead||!wanted||token!==version||hidden())audio.pause();blocked=false;
 }catch(e){if(token===version&&wanted)blocked=e.name==='NotAllowedError';}paint();}
 function toggle(){if(dead)return;if(wanted&&!audio.paused){pause();return;}wanted=true;blocked=false;if(baseline)shared.paused.delete(baseline.id);if(audio.ended)audio.currentTime=0;play();}
 const controller={stop,pause,toggle,get dead(){return dead;}};
 on(audio,'play',paint);on(audio,'pause',paint);on(audio,'timeupdate',paint);on(audio,'loadedmetadata',paint);on(audio,'ended',()=>{if(!audio.loop)pause();});
 on(doc,'visibilitychange',()=>{if(doc.hidden)pause();});
